    tip: 'green', success: 'green', check: 'green',
    warning: 'yellow', caution: 'yellow', attention: 'yellow',
    danger: 'red', error: 'red', failure: 'red', bug: 'red',
    note: 'gray', quote: 'gray', cite: 'gray',
