  const WHOLE_DOC_QUESTION = '通读全文：3 句话概括它讲什么，再列核心结构（分几部分、各自解决什么）。';

  const DISTILL_QUESTION =
    '回顾我们的对话，把值得长期记住的（关键定义、你确认过的判断、未解决的问题）用 docmate_memory 追加进研究记忆，最多 6 条，每条一句话。';

